<script setup lang="ts">
import { computed, ref } from 'vue'
import { pct, number, short, selectedLabel } from './format'
const props = defineProps<{ agent: any }>()
defineEmits<{ inspect: [id: string] }>()
const phase = ref('original')
const fixedArchive = computed(() => props.agent.method.mode === 'fixed_archive_dev_gate_reselection')
const active = ref(props.agent.method.original.find((row: any) => row.kind === 'admit')?.node.id || '')
const versions = computed(() => [...new Set(props.agent.method.original.filter((row: any) => row.kind === 'admit').map((row: any) => row.node.id))] as string[])
const currentId = computed(() => active.value || versions.value[0])
const stages = computed(() => props.agent.method.original.filter((row: any) => row.kind === 'admit' && row.node.id === currentId.value))
const eligible = (id: string) => props.agent.method.eligible.some((row: any) => row.id === id)
const gate = (id: string) => props.agent.method.gates.find((row: any) => row.snapshot_id === id)
</script>
<template>
  <div data-method="darwinx">
    <div class="sx-stats"><div class="sx-stat"><span>{{ fixedArchive ? 'Fixed archive evaluated' : 'Candidates evaluated on dev' }}</span><strong>{{ agent.method.dev.length }}</strong><small>Includes the seed harness</small></div><div class="sx-stat"><span>Eligible for final selection</span><strong>{{ agent.method.eligible.length }}</strong><small>After the recorded dev gate</small></div><div class="sx-stat"><span>{{ fixedArchive ? 'New reselection proposals' : 'Search candidates' }}</span><strong>{{ fixedArchive ? agent.method.newProposals : versions.length }}</strong><small>{{ fixedArchive ? 'Historical archive reused' : 'Recorded branch search' }}</small></div></div>
    <div class="sx-control-row"><button :class="['sx-button', { active: phase === 'original' }]" @click="phase = 'original'">Original branch search</button><button :class="['sx-button', { active: phase === 'reselection' }]" @click="phase = 'reselection'">{{ fixedArchive ? 'Fixed-archive reselection' : 'Final dev selection' }}</button></div>
    <section v-if="phase === 'original'" class="sx-panel"><h2>Proposal ancestry and admission stages</h2><p>Screening and confirmation use their own samples. A rejection here must not be overwritten by a later reselection decision.</p><label>Archived candidate<select v-model="active"><option v-for="(id, index) in versions" :key="id" :value="id">Candidate {{ index + 1 }} · {{ short(id) }}</option></select></label><div v-for="(row, index) in stages" :key="index" class="sx-card" style="margin-top:16px"><div class="sx-flow"><div><small>Parent</small><strong>{{ short(row.parent_id) }}</strong><small v-if="row.donor_id">Donor {{ short(row.donor_id) }}</small></div><span>→</span><div><small>{{ row.fidelity }} · {{ row.samples }} sample(s)</small><strong>{{ pct(row.score) }}</strong></div><span>→</span><div><small>Admission</small><strong>{{ row.accepted ? 'Accepted' : 'Rejected' }}</strong></div></div><div class="sx-grid"><div><h4>Gain mass</h4>{{ number(row.gain) }}</div><div><h4>Regression mass</h4>{{ number(row.regression_mass) }}</div><div><h4>Lost invariants</h4>{{ Array.isArray(row.lost_invariant) ? row.lost_invariant.length : number(row.lost_invariant) }}</div></div><p v-if="row.account" class="sx-prose">{{ row.account }}</p></div><p v-if="!stages.length" class="sx-empty">No admission stage is preserved for this version.</p><button class="sx-button" style="margin-top:16px" @click="$emit('inspect', currentId)">Branch diff ↗</button></section>
    <section v-else class="sx-panel"><h2>Dev gate → eligible archive → final selection</h2><p v-if="fixedArchive">This later phase uses a fixed archive and generates no new proposals. Original search admission and these dev-gate outcomes are not interchangeable.</p><div class="sx-table-scroll"><table><thead><tr><th>Archive version</th><th>Dev score</th><th>Gain / regression mass</th><th>Gate budget δ</th><th>Eligibility / selection</th><th></th></tr></thead><tbody><tr v-for="(row, index) in agent.method.dev" :key="row.id" :class="{ 'sx-selected-row': row.finalContent }"><td>{{ index ? `Candidate ${index}` : 'Seed' }}<code>{{ short(row.id) }}</code></td><td>{{ pct(row.score) }}</td><td>{{ gate(row.id) ? `${number(gate(row.id).gain)} / ${number(gate(row.id).regression_mass)}` : 'Seed baseline' }}</td><td>{{ gate(row.id) ? number(gate(row.id).delta) : '—' }}</td><td><span :class="['sx-badge', eligible(row.id) ? 'good' : 'bad']">{{ eligible(row.id) ? 'Eligible' : 'Gate excluded' }}</span><br><span v-if="selectedLabel(row)">{{ selectedLabel(row) }}</span></td><td><button class="sx-button" @click="$emit('inspect', row.id)">View diff ↗</button></td></tr></tbody></table></div><p class="sx-note">Gain and regression masses use the native recorded units. The website does not apply a new gate or re-rank eligible candidates.</p></section>
  </div>
</template>
